(()=>{
'use strict';
const L=window.DCMLogic,E=L.E,TARGET=.95,DATA_KEY='dcm-vendor-v1-data',ACTION_KEY='dcm-vendor-v1-actions';
const $=id=>document.getElementById(id);
const reasons={'01':'시스템 미구축','02':'거래처 사용거부','03':'ERP Interface 오류','04':'Master 불일치','05':'신규거래처','06':'공급중단 예정','07':'사용법 미숙','08':'데이터 오류','09':'확인 중','99':'기타'};
let data=load(DATA_KEY,[]),actions=load(ACTION_KEY,[]);
function load(k,f){try{const x=JSON.parse(localStorage.getItem(k));return Array.isArray(x)?x:f;}catch(e){return f;}}
function save(){localStorage.setItem(DATA_KEY,JSON.stringify(data));localStorage.setItem(ACTION_KEY,JSON.stringify(actions));}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function pct(v){return v==null?'—':(v*100).toFixed(1)+'%';}
function pp(v){return v==null||!Number.isFinite(v)?'—':`${v>=0?'+':''}${(v*100).toFixed(1)}%p`;}
function key(r){return `${r.outlet}|||${r.businessNo}`;}
function months(){return [...new Set(data.map(r=>r.month).filter(Boolean))].sort();}
function monthLabel(m){if(!m)return '—';const [y,mm]=m.split('-');return `${y}년 ${Number(mm)}월`;}
function scope(m){const o=$('outlet').value||'전체';return data.filter(r=>r.month===m&&(o==='전체'||r.outlet===o));}
function refresh(preserve=true){const oldO=$('outlet').value,oldM=$('month').value,outs=[...new Set(data.map(r=>r.outlet).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko'));$('outlet').innerHTML=['전체',...outs].map(x=>`<option>${esc(x)}</option>`).join('');$('outlet').value=preserve&&['전체',...outs].includes(oldO)?oldO:'전체';const ms=months();$('month').innerHTML=ms.map(m=>`<option value="${m}">${monthLabel(m)}</option>`).join('');$('month').value=preserve&&ms.includes(oldM)?oldM:(ms.at(-1)||'');}
function streakRows(cur,curr){const currentKeys=new Set(curr.map(key)),ms=months().filter(m=>m<=cur),by=new Map();data.filter(r=>ms.includes(r.month)).forEach(r=>{const k=key(r);if(!by.has(k))by.set(k,{});by.get(k)[r.month]=r;});const out=[];by.forEach(hist=>{const r=hist[cur];if(!r||!currentKeys.has(key(r)))return;const entityStreak={};let streak=0;E.forEach(e=>{let n=0;for(let i=ms.length-1;i>=0;i--){if(L.normStatus(hist[ms[i]]?.statuses?.[e])==='X')n++;else break;}entityStreak[e]=n;streak=Math.max(streak,n);});out.push({...r,entityStreak,streak});});return out;}
function risks(cur,curr,prior,ch){const pmap=new Map(prior.map(r=>[key(r),r])),o2x=new Set(ch.oToX.map(x=>`${x.outlet}|||${x.businessNo}|||${x.entity}`));return streakRows(cur,curr).filter(r=>E.some(e=>L.normStatus(r.statuses?.[e])==='X')).map(r=>{let score=0,currentXScore=0,persistScore=0,degradeScore=0,newXScore=0,xCount=0;E.forEach(e=>{if(L.normStatus(r.statuses?.[e])!=='X')return;xCount++;score+=2;currentXScore+=2;const st=r.entityStreak[e]||0;if(st>=2){const add=3*Math.min(st-1,3);score+=add;persistScore+=add;}if(o2x.has(`${r.outlet}|||${r.businessNo}|||${e}`)){score+=4;degradeScore+=4;}if(!L.normStatus(pmap.get(key(r))?.statuses?.[e])){score+=2;newXScore+=2;}});const priority=score>=12?'P1':score>=8?'P2':score>=4?'P3':'P4';return {...r,score,currentXScore,persistScore,degradeScore,newXScore,xCount,priority};}).sort((a,b)=>b.score-a.score||b.xCount-a.xCount||String(a.businessName).localeCompare(String(b.businessName),'ko'));}
function scoreDetail(r){return [['현재X',r.currentXScore],['지속X',r.persistScore],['O→X',r.degradeScore],['신규X',r.newXScore]].filter(x=>x[1]).map(x=>`${x[0]} ${x[1]}`).join(' + ');}
function actionFor(r){return actions.find(a=>a.key===key(r))||{};}
function statusLabel(s){return ({TODO:'미조치',IN_PROGRESS:'진행중',WAITING:'회신대기',DONE:'완료'})[s]||'미조치';}
function render(){const cur=$('month').value;if(!cur){renderEmpty();return;}const ms=months(),i=ms.indexOf(cur),prev=i>0?ms[i-1]:null,curr=scope(cur),prior=prev?scope(prev):[],s=L.summarize(curr),ps=L.summarize(prior),ch=L.compare(prior,curr),rr=risks(cur,curr,prior,ch),persistent=rr.filter(r=>r.streak>=2);$('scopeLabel').textContent=`${$('outlet').value} · ${monthLabel(cur)}`;
$('ctRate').textContent=pct(s.rate);$('ctDelta').textContent=prev&&ps.rate!=null&&s.rate!=null?pp(s.rate-ps.rate):'—';$('ctX').textContent=s.X.toLocaleString();$('ctX2O').textContent=ch.xToO.length.toLocaleString();$('ctO2X').textContent=ch.oToX.length.toLocaleString();$('ctPersist').textContent=persistent.reduce((n,r)=>n+E.filter(e=>(r.entityStreak[e]||0)>=2).length,0).toLocaleString();
const aging={m1:0,m2:0,m3:0,m46:0,m6:0};rr.forEach(r=>E.forEach(e=>{const n=r.entityStreak[e]||0;if(n===1)aging.m1++;else if(n===2)aging.m2++;else if(n===3)aging.m3++;else if(n>=4&&n<=6)aging.m46++;else if(n>6)aging.m6++;}));[['ctAge1',aging.m1],['ctAge2',aging.m2],['ctAge3',aging.m3],['ctAge46',aging.m46],['ctAge6',aging.m6]].forEach(([id,v])=>$(id).textContent=v.toLocaleString());const gap=s.rate==null?null:Math.max(0,TARGET-s.rate),need=s.evaluated?Math.ceil(Math.max(0,TARGET*s.evaluated-s.O)):0;$('ctTargetNow').textContent=pct(s.rate);$('ctTargetGap').textContent=gap==null?'—':pp(-gap);$('ctTargetNeed').textContent=`${need.toLocaleString()}건`;
$('ctRiskBody').innerHTML=rr.slice(0,20).map((r,n)=>`<tr><td>${n+1}</td><td><span class="ct-priority ct-${r.priority.toLowerCase()}">${r.priority}</span></td><td>${esc(r.outlet)}</td><td>${esc(r.businessName)}</td><td class="mono">${esc(r.businessNo)}</td><td>${E.map(e=>L.normStatus(r.statuses?.[e])||'-').join(' / ')}</td><td>${r.streak}M</td><td><b>${r.score}</b><br><small>${esc(scoreDetail(r))}</small></td><td><button class="ct-btn" data-open="${esc(key(r))}">상세</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">미연동 위험 거래처가 없습니다.</td></tr>';
$('ctActionBody').innerHTML=rr.slice(0,30).map(r=>{const a=actionFor(r);return `<tr><td><span class="ct-priority ct-${r.priority.toLowerCase()}">${r.priority}</span></td><td>${esc(r.businessName)}</td><td>${esc(r.outlet)}</td><td>${r.streak}M</td><td><select data-field="reasonCode" data-key="${esc(key(r))}"><option value="">원인 선택</option>${Object.entries(reasons).map(([k,v])=>`<option value="${k}" ${a.reasonCode===k?'selected':''}>${k} ${v}</option>`).join('')}</select></td><td><input type="text" data-field="plan" data-key="${esc(key(r))}" value="${esc(a.plan||'')}" placeholder="조치계획"></td><td><input type="date" data-field="dueDate" data-key="${esc(key(r))}" value="${esc(a.dueDate||'')}"></td><td><select data-field="status" data-key="${esc(key(r))}">${['TODO','IN_PROGRESS','WAITING','DONE'].map(x=>`<option value="${x}" ${(a.status||'TODO')===x?'selected':''}>${statusLabel(x)}</option>`).join('')}</select></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Action 대상이 없습니다.</td></tr>';
const rkeys=new Set(rr.map(key)),used={};actions.filter(a=>rkeys.has(a.key)&&a.reasonCode).forEach(a=>used[a.reasonCode]=(used[a.reasonCode]||0)+1);const total=Object.values(used).reduce((a,b)=>a+b,0)||1;$('ctReasonBars').innerHTML=Object.entries(used).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="ct-bar-row"><span>${esc(reasons[k]||k)}</span><div class="ct-bar"><i style="width:${v/total*100}%"></i></div><b>${v}</b></div>`).join('')||'<div class="ct-note">Action Board에서 원인코드를 입력하면 자동 집계됩니다.</div>';
const outs=[...new Set(curr.map(r=>r.outlet))].map(o=>{const cs=L.summarize(curr.filter(r=>r.outlet===o)),prs=L.summarize(prior.filter(r=>r.outlet===o));return {o,rate:cs.rate,x:cs.X,delta:prev&&prs.rate!=null&&cs.rate!=null?cs.rate-prs.rate:null};}),worst=[...outs].sort((a,b)=>(a.rate??1)-(b.rate??1))[0],mostX=[...outs].sort((a,b)=>b.x-a.x)[0];$('ctAi').innerHTML=`<div class="ct-note">분석 범위: ${esc($('outlet').value)} · ${monthLabel(cur)}</div><strong>${monthLabel(cur)} 요약</strong><br>• 전체 연동률 <strong>${pct(s.rate)}</strong>${prev&&ps.rate!=null?`, 전월 대비 <strong>${pp(s.rate-ps.rate)}</strong>`:''}<br>• 미연동 X <strong>${s.X}건</strong>, X→O <strong>${ch.xToO.length}건</strong>, O→X <strong>${ch.oToX.length}건</strong><br>• ${mostX?`미연동 최다 권역: <strong>${esc(mostX.o)} X ${mostX.x}</strong>`:'업체 데이터 없음'}<br>• ${worst?`연동률 최저 권역: <strong>${esc(worst.o)} ${pct(worst.rate)}</strong>`:''}<br><br><strong>Recommended Action</strong><br>1. O→X ${ch.oToX.length}건 우선 복구 확인<br>2. 2개월 이상 지속 X ${persistent.length}개 거래처 집중관리<br>3. P1 ${rr.filter(r=>r.priority==='P1').length}개 즉시 조치<br>4. 95% 목표까지 ${need}건 추가 O 전환 필요`;
renderDetail(cur,prev,curr,prior,s,ps,ch);renderReport(cur,s,ps,ch,rr,need);bindDynamic(rr);}
function renderDetail(cur,prev,curr,prior,s,ps,ch){$('kpiRate').textContent=pct(s.rate);$('kpiRateSub').textContent=s.evaluated?`평가 ${s.evaluated}건 중 O ${s.O}건`:'평가 데이터 없음';$('kpiEval').textContent=s.X;$('kpiAbs').textContent=s.needAbsolute;$('kpiSupply').textContent=s.suppliedAbsolute;$('entityCards').innerHTML=E.map(e=>{const x=s.byEntity[e];return `<div class="entity-card"><div class="entity-name">${e}</div><div class="entity-rate">${pct(x.rate)}</div><div class="meter"><i style="width:${x.rate?x.rate*100:0}%"></i></div><div class="mini"><span>O ${x.O}</span><span>X ${x.X}</span></div></div>`}).join('');const outs=[...new Set(curr.map(r=>r.outlet))].sort((a,b)=>a.localeCompare(b,'ko'));$('outletBody').innerHTML=outs.map(o=>{const x=L.summarize(curr.filter(r=>r.outlet===o));return `<tr><td>${esc(o)}</td>${E.map(e=>`<td>${pct(x.byEntity[e].rate)} <small>O ${x.byEntity[e].O}/X ${x.byEntity[e].X}</small></td>`).join('')}<td><b>${pct(x.rate)}</b></td><td>${x.X}</td><td>${x.needAbsolute}</td><td>${x.suppliedAbsolute}</td></tr>`}).join('');$('changeTitle').textContent=prev?`${monthLabel(prev)} 대비 ${monthLabel(cur)}`:`${monthLabel(cur)} (이전 월 없음)`;$('changeSub').textContent='현재 업체/권역 필터 기준';$('deltaRate').textContent=prev&&ps.rate!=null&&s.rate!=null?pp(s.rate-ps.rate):'—';$('supplyDelta').textContent=prev?`${ps.suppliedAbsolute} → ${s.suppliedAbsolute}`:'—';$('x2o').textContent=ch.xToO.length;$('o2x').textContent=ch.oToX.length;$('newSupply').textContent=ch.newSupply.length;$('stopSupply').textContent=ch.stoppedSupply.length;const needs=L.needList(curr);$('needCount').textContent=`${new Set(needs.map(r=>r.businessNo)).size}처`;$('needBody').innerHTML=needs.map(r=>`<tr><td>${esc(r.outlet)}</td><td class="mono">${esc(r.businessNo)}</td><td>${esc(r.businessName)}</td>${E.map(e=>`<td><span class="badge ${L.normStatus(r.statuses[e])==='O'?'ok':'bad'}">${L.normStatus(r.statuses[e])||'-'}</span></td>`).join('')}<td><b>${r.xCount}</b></td></tr>`).join('')||'<tr><td colspan="7" class="empty">연동 필요처가 없습니다.</td></tr>';}
function renderEmpty(){['ctRate','ctDelta','ctX','ctX2O','ctO2X','ctPersist','ctTargetNow','ctTargetGap','ctTargetNeed','kpiRate','kpiEval','kpiAbs','kpiSupply'].forEach(id=>{if($(id))$(id).textContent='-';});['ctAge1','ctAge2','ctAge3','ctAge46','ctAge6'].forEach(id=>$(id).textContent='0');}
function upsert(k,field,value){let a=actions.find(x=>x.key===k);if(!a){const [outlet,businessNo]=k.split('|||');a={key:k,outlet,businessNo,history:[]};actions.push(a);}a[field]=value;a.updatedAt=new Date().toISOString();a.history.unshift({at:a.updatedAt,field,value});a.history=a.history.slice(0,50);save();render();}
function bindDynamic(rr){document.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>upsert(el.dataset.key,el.dataset.field,el.value));document.querySelectorAll('[data-open]').forEach(btn=>btn.onclick=()=>{const r=rr.find(x=>key(x)===btn.dataset.open);if(!r)return;const a=actionFor(r),hist=data.filter(x=>key(x)===key(r)).sort((a,b)=>a.month.localeCompare(b.month));$('ctModalTitle').textContent=r.businessName;$('ctModalBody').innerHTML=`<p><b>${esc(r.outlet)}</b> · ${esc(r.businessNo)}</p><p>Risk <b>${r.priority} / ${r.score}점</b> · ${esc(scoreDetail(r))}</p><table><thead><tr><th>월</th>${E.map(e=>`<th>${e}</th>`).join('')}</tr></thead><tbody>${hist.map(x=>`<tr><td>${monthLabel(x.month)}</td>${E.map(e=>`<td>${L.normStatus(x.statuses?.[e])||'-'}</td>`).join('')}</tr>`).join('')}</tbody></table><h3>Action</h3><p>원인 ${esc(reasons[a.reasonCode]||'미입력')} · 상태 ${statusLabel(a.status)} · Due ${esc(a.dueDate||'-')}</p><p>${esc(a.plan||'조치계획 미입력')}</p>`;$('ctModal').classList.add('open');});}
function normalizeOutlet(v){return String(v??'').trim()||'업체';}
function bizNo(v){return String(v??'').trim().replace(/\.0$/,'').replace(/\D/g,'');}
function fileYear(name){const m=String(name).match(/(?:^|\D)(\d{2})(\d{2})(?:\D|$)/);return m?2000+Number(m[1]):new Date().getFullYear();}
async function parseWorkbook(file){if(!window.XLSX)throw new Error('Excel 라이브러리를 불러오지 못했습니다.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),year=fileYear(file.name),out=[];wb.SheetNames.forEach(sh=>{const mm=sh.trim().match(/^(\d{1,2})월$/);if(!mm)return;const aoa=XLSX.utils.sheet_to_json(wb.Sheets[sh],{header:1,defval:null,raw:true});if(!aoa.length)return;const hdr=aoa[0].map(x=>String(x??'').trim()),idx=Object.fromEntries(hdr.map((x,i)=>[x,i]));if(idx['도매상명']==null||idx['실사업자번호']==null||idx['실사업자명']==null)return;const month=`${year}-${String(Number(mm[1])).padStart(2,'0')}`,map=new Map();aoa.slice(1).forEach(row=>{const b=bizNo(row[idx['실사업자번호']]);if(!b)return;const outlet=normalizeOutlet(row[idx['도매상명']]),k=`${month}|||${outlet}|||${b}`;if(!map.has(k))map.set(k,{month,outlet,manager:'',businessNo:b,businessName:String(row[idx['실사업자명']]??'').trim(),statuses:Object.fromEntries(E.map(e=>[e,null]))});const rec=map.get(k);E.forEach(e=>{if(idx[e]==null)return;const v=L.normStatus(row[idx[e]]);if(v)rec.statuses[e]=(rec.statuses[e]&&rec.statuses[e]!==v)?'X':v;});});out.push(...map.values());});return out;}
async function upload(files){const all=[];for(const f of files)all.push(...await parseWorkbook(f));if(!all.length)throw new Error('인식 가능한 월 시트와 필수 열을 찾지 못했습니다.');const pairs=new Set(all.map(r=>`${r.month}|||${r.outlet}`));data=data.filter(r=>!pairs.has(`${r.month}|||${r.outlet}`));const map=new Map(data.map(r=>[`${r.month}|||${r.outlet}|||${r.businessNo}`,r]));all.forEach(r=>map.set(`${r.month}|||${r.outlet}|||${r.businessNo}`,r));data=[...map.values()];save();refresh(false);render();$('uploadMsg').textContent=`업데이트 완료 · ${all.length.toLocaleString()}건 반영 · ${[...pairs].length}개 월/업체 범위`;}
function renderReport(cur,s,ps,ch,rr,need){$('ctReport').innerHTML=`<h1>${monthLabel(cur)} DCM 자가점검 보고</h1><p>업체/권역: ${esc($('outlet').value)}</p><div class="ct-print-kpis"><div>연동률<br><b>${pct(s.rate)}</b></div><div>전월비<br><b>${ps.rate!=null&&s.rate!=null?pp(s.rate-ps.rate):'—'}</b></div><div>미연동 X<br><b>${s.X}</b></div><div>95% 목표 필요<br><b>${need}건</b></div></div><h2>Risk</h2><p>P1 ${rr.filter(r=>r.priority==='P1').length}개 · P2 ${rr.filter(r=>r.priority==='P2').length}개 · O→X ${ch.oToX.length}건</p>`;}
function downloadCSV(){const cur=$('month').value,rows=L.needList(scope(cur)),table=[['업체/권역','실사업자번호','실사업자명',...E,'X 평가처수'],...rows.map(r=>[r.outlet,r.businessNo,r.businessName,...E.map(e=>r.statuses[e]||''),r.xCount])],csv='\ufeff'+table.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`DCM_연동필요_${cur}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function init(){refresh(false);render();$('outlet').onchange=render;$('month').onchange=render;$('fileInput').onchange=async e=>{try{await upload([...e.target.files]);}catch(err){alert(err.message);}finally{e.target.value='';}};$('resetBtn').onclick=()=>{if(confirm('업로드 데이터와 Action 이력을 모두 초기화할까요?')){data=[];actions=[];save();refresh(false);render();$('uploadMsg').textContent='업로드 데이터가 초기화되었습니다.';}};$('backupBtn').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),data,actions},null,2)],{type:'application/json'}));a.download='DCM_vendor_backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);};$('backupInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const fr=new FileReader();fr.onload=()=>{try{const x=JSON.parse(fr.result);if(!Array.isArray(x.data))throw 0;data=x.data;actions=Array.isArray(x.actions)?x.actions:[];save();refresh(false);render();}catch(err){alert('올바른 업체용 DCM 백업 파일이 아닙니다.');}};fr.readAsText(f);};$('ctPrint').onclick=()=>window.print();$('ctClose').onclick=()=>$('ctModal').classList.remove('open');$('needCsv').onclick=downloadCSV;document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{const t=$(b.dataset.jump);if(t?.tagName==='DETAILS')t.open=true;t?.scrollIntoView({behavior:'smooth',block:'start'});});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();